  const x = 10;
  const person = {
    name: "Tarmeez",
    age: 20,
  }
  return (
    <div>
    <h1 >{person.name}{sayhello()}</h1>
    <h2>{x + 10} My First Component2</h2>
    <h3>{10}My First Component2 x + 10</h3>
     <button onClick={sayhello}>click on</button>
    </div>
  ) 
}

function sayhello() {
  alert("Hello Tarmeez");
}
